function injectNavigationStyles(){if(document.getElementById("navigation-styles"))return;const style=document.createElement("style");style.id="navigation-styles";style.textContent='.navigation-controls{margin:8px 0 10px;position:relative}.navigation-groups{display:grid;gap:5px;grid-template-columns:repeat(3,minmax(0,1fr));margin-bottom:7px}.navigation-group{background:#e7eee9;color:#345143;font-size:11px;padding:8px 5px}.navigation-group.active{background:#217346;color:#fff}.navigation-controls input[type="search"]{border:1px solid #cdd9d1;border-radius:7px;font:inherit;padding:9px 10px;width:100%}.grouped-tabs{flex-wrap:wrap;overflow-x:visible;padding-bottom:7px}.grouped-tabs .tab{flex:1 1 auto}.tool-search-results{background:#fff;border:1px solid #cdd9d1;border-radius:8px;box-shadow:0 8px 24px rgba(21,73,45,.16);left:0;max-height:260px;overflow:auto;padding:6px;position:absolute;right:0;top:70px;z-index:20}.tool-search-result{background:#f4f7f5;color:#234333;display:block;font-size:11px;margin:3px 0;text-align:left;width:100%}.tool-search-results p{margin:8px}';document.head.appendChild(style);}
const NAV_GROUPS={main:{label:"Основное",panels:["analysis","cleaning","duplicates","compare","report"]},tools:{label:"Инструменты",panels:["cells","formula-tools","transform","data-tools","sheets"]},ai:{label:"AI",panels:["ai-tools"]},desktop:{label:"Desktop",panels:["desktop-pro"]},system:{label:"Журнал",panels:["history"]}};
