async function createDynamicTable(){await run("Создание автоматически расширяемой таблицы",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","rowCount","columnCount"]);await c.sync();requireSize(r);if(r.rowCount<2||r.columnCount<1)throw new Error("Выделите строку заголовков и хотя бы одну строку данных.");const headers=r.values[0].map(value=>String(value??"").trim());if(headers.some(value=>!value))throw new Error("Все ячейки первой строки должны содержать заголовки.");if(new Set(headers.map(value=>value.toLocaleLowerCase())).size!==headers.length)throw new Error("Заголовки таблицы должны быть уникальными.");const backupInfo=await backup(c,r,"Резерв_таблица"),table=c.workbook.tables.add(r.address,true);table.load("name");await c.sync();show("data-tools-result",`Создана автоматически расширяемая таблица ${table.name}.\nДиапазон: ${r.address}\nРезерв: ${backupInfo.sheet}`);});}
async function applyPrecision(){const digits=Math.max(0,Math.min(15,Number(document.getElementById("precision-digits")?.value)||0));await run("Настройка точности",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","formulas","rowCount","columnCount"]);await c.sync();requireSize(r);const backupInfo=await backup(c,r,"Резерв_точность"),output=r.formulas.map((row,i)=>row.map((formula,j)=>{if(typeof formula==="string"&&formula.startsWith("="))return`=ROUND(${formula.slice(1)},${digits})`;const value=r.values[i][j];return typeof value==="number"&&Number.isFinite(value)?Number(value.toFixed(digits)):value;}));r.formulas=output;await c.sync();show("cells-result",`Точность ${digits} знаков применена к ${r.address}.\nРезерв: ${backupInfo.sheet}`);});}
