restoreLast=async function(){lastBackup=lastBackup||safeJsonSetting("eda-backup",null,x=>x&&typeof x.sheet==="string"&&typeof x.target==="string");if(!lastBackup){setStatus("Нет резервной копии.",true);return;}if(lastBackup.document!==undefined&&lastBackup.document!==currentDocumentKey()){setStatus("Эта резервная копия принадлежит другой книге.",true);return;}await run("Восстановление",async c=>{if(lastBackup.table){const table=c.workbook.tables.getItemOrNullObject(lastBackup.table);table.load("isNullObject");await c.sync();if(!table.isNullObject)table.delete();}const src=c.workbook.worksheets.getItem(lastBackup.sheet).getUsedRange(),target=rangeFromAddress(c,lastBackup.target);src.load(["rowCount","columnCount"]);await c.sync();target.clear("All");target.getCell(0,0).getResizedRange(src.rowCount-1,src.columnCount-1).copyFrom(src,"All");await c.sync();setStatus(`Восстановлено из ${lastBackup.sheet}.`);});};
createDynamicTable=async function(){await run("Создание автоматически расширяемой таблицы",async c=>{const r=c.workbook.getSelectedRange();r.load(["address","values","rowCount","columnCount"]);await c.sync();requireSize(r);if(r.rowCount<2||r.columnCount<1)throw new Error("Выделите строку заголовков и хотя бы одну строку данных.");const headers=r.values[0].map(value=>String(value??"").trim());if(headers.some(value=>!value))throw new Error("Все ячейки первой строки должны содержать заголовки.");if(new Set(headers.map(value=>value.toLocaleLowerCase())).size!==headers.length)throw new Error("Заголовки таблицы должны быть уникальными.");const b=await backup(c,r,"Резерв_таблица"),table=c.workbook.tables.add(r.address,true);table.load("name");await c.sync();b.table=table.name;lastBackup=b;localStorage.setItem("eda-backup",JSON.stringify(b));show("data-tools-result",`Создана автоматически расширяемая таблица ${table.name}.\nДиапазон: ${r.address}\nРезерв: ${b.sheet}`);});};
getAiUsageTotal=function(){return safeJsonSetting("eda-ai-usage",{requests:0,inputTokens:0,outputTokens:0,estimatedCostUsd:0},x=>x&&typeof x==="object"&&Number.isFinite(Number(x.requests))&&Number.isFinite(Number(x.inputTokens))&&Number.isFinite(Number(x.outputTokens))&&Number.isFinite(Number(x.estimatedCostUsd)));};
