restoreClearedHistory=function(){const saved=safeJsonSetting("eda-cleared-history",null,isHistory);if(!saved?.length){setStatus("Нет сохранённого очищенного журнала.",true);return;}history=saved;saveHistory();renderHistory();localStorage.removeItem("eda-cleared-history");setStatus(`Журнал восстановлен: ${history.length} записей.`);};
checkCompanion=async function(silent=false){detectEnvironment();if(!desktopState.isDesktop){if(!silent)show("desktop-result","Локальный мост проверяется только в настольном Excel.");return false;}if(!silent)toggle(true);try{desktopState.token="";const info=await companionRequest("health");desktopState.bridge=info?.product==="Excel Data Assistant Companion"&&Number(info.protocol)===3;desktopState.token=desktopState.bridge?String(info.sessionToken||""):"";desktopState.bridgeVersion=desktopState.bridge?String(info.version||"—"):"—";desktopState.protocol=Number(info.protocol)||0;desktopState.uptime=Number(info.uptimeSeconds)||0;desktopState.excelRunning=Boolean(info.excelRunning);if(!desktopState.bridge)throw new Error("Несовместимая версия протокола локального моста.");if(!silent)show("desktop-result",`Локальный мост подключён. Версия: ${info.version||"не указана"}`);return true;}catch(error){desktopState.bridge=false;desktopState.token="";desktopState.bridgeVersion="—";desktopState.protocol=0;desktopState.uptime=0;desktopState.excelRunning=false;if(!silent)show("desktop-result",error.message||"Локальный мост пока не установлен или не запущен.");return false;}finally{renderEnvironment();if(!silent)toggle(false);}};
